declare(strict_types=1);require_once dirname(__DIR__,2).'/config.php';require_once BASE_PATH.'/shared/delivery/ReleaseFlags.php';
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
if(DELIVERY_ENABLED!==true&&DELIVERY_SETUP_ENABLED!==true){http_response_code(503);exit('Delivery setup is not enabled.');}
require_once BASE_PATH.'/apps/operations/operations.php';require_login();require_once BASE_PATH.'/shared/delivery/FrontSession.php';require_once BASE_PATH.'/shared/delivery/PartnerRouting.php';
