$_SESSION['delivery_front_csrf']??=bin2hex(random_bytes(32));$message='';
if($_SERVER['REQUEST_METHOD']==='POST')try{\Hambelela\Delivery\FrontSession::csrf((string)($_POST['csrf']??''));\Hambelela\Delivery\PartnerRouting::save(db(),$actor['id'],(int)($_POST['partner']??0),(int)($_POST['driver']??0),(string)($_POST['reason']??''));$message='Routing saved. New requests will appear on the selected Driver’s queue. Existing assignments are unchanged.';}catch(DomainException $e){$message=$e->getMessage();}catch(Throwable $e){http_response_code(503);$message='Routing could not be saved.';}
