?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Partner routing · Hambelela</title><link rel="stylesheet" href="<?=htmlspecialchars(BASE_URL,ENT_QUOTES)?>/assets/css/delivery-core.css?v=<?=filemtime(BASE_PATH.'/assets/css/delivery-core.css')?>"><link rel="stylesheet" href="<?=htmlspecialchars(BASE_URL,ENT_QUOTES)?>/assets/css/delivery-controls.css?v=<?=filemtime(BASE_PATH.'/assets/css/delivery-controls.css')?>"></head><body data-delivery-ui><main class="delivery-login"><div class="eyebrow">OWNER · DELIVERY ROUTING</div><h1>Partner Driver</h1><p>Explicitly choose the verified Driver for new partner requests. No name-based or automatic employee matching is used.</p><p role="status"><?=htmlspecialchars($message,ENT_QUOTES)?></p><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['delivery_front_csrf'],ENT_QUOTES)?>"><label>Partner<select name="partner" required><option value="">Choose partner</option><?php foreach($partners as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'],ENT_QUOTES)?> · Driver ID <?=\Hambelela\Delivery\PartnerRouting::driver(db(),(int)$p['id'])?:'not configured'?></option><?php endforeach;?></select></label><label>Verified Driver<select name="driver" required><option value="">Choose Driver</option><?php foreach($drivers as $d):?><option value="<?=(int)$d['id']?>"><?=htmlspecialchars($d['full_name'],ENT_QUOTES)?> · <?=(int)$d['id']?></option><?php endforeach;?></select></label><label>Verification / change reason<input name="reason" minlength="5" maxlength="500" required></label><button class="primary">Save routing</button></form><div class="actions"><a class="secondary" href="partner-setup.php">Partner accounts</a><a class="secondary" href="driver-setup.php">Driver accounts</a><a class="secondary" href="index.php">Delivery workspace</a></div></main></body></html>
